legacy-bash[/Users/zious/.claude/plugins/cache/claude-mp/vsdd-factory/1.0.0-rc.23/hooks/destructive-command-guard.sh] stderr: BLOCKED by destructive-command-guard: rm -rf on protected path detected: cd /Users/zious/Documents/GITHUB/vsdd-factory && tmpd=$(mktemp -d)
deps_file="${tmpd}/deps.txt"
depth_file="${tmpd}/depth.txt"
story_index=".factory/stories/STORY-INDEX.md"

# Build deps map (same logic as T-14)
awk -F'|' '
  /^\| S-/ && !/\*\*retired\*\*/ && !/\*\*withdrawn\*\*/ {
    sid=$2; gsub(/^[[:space:]]+|[[:space:]]+$/, "", sid)
    raw=$7; gsub(/^[[:space:]]+|[[:space:]]+$/, "", raw)
    print sid "|" raw
  }
' "${story_index}" | awk -F'|' '
{
  sid=$1; raw=$2; deps=""
  expanded = raw
  if (raw ~ /^E-8([[:space:]]|$)/) {
    sub(/^E-8[[:space:]A-Za-z0-9._-]*/, \
      "S-8.00 S-8.01 S-8.02 S-8.03 S-8.04 S-8.05 S-8.06 S-8.07 S-8.08 S-8.09 S-8.10 S-8.30", \
      expanded)
  }
  if (expanded ~ /E-9([[:space:]]|$)/) {
    sub(/E-9[[:space:]A-Za-z0-9._-]*/, \
      "S-9.00 S-9.01 S-9.02 S-9.03 S-9.04 S-9.05 S-9.06 S-9.07", expanded)
  }
  raw = expanded
  # Extract explicit S-N.M tokens
  clean = raw
  gsub(/S-[0-9]+\.[0-9]+\.\.S-[0-9]+\.[0-9]+/, "", clean)
  n = split(clean, toks, /[^S0-9.A-Za-z_-]+/)
  for (i=1; i<=n; i++) {
    t = toks[i]
    if (t ~ /^S-[0-9]+\.[0-9]/) {
      if (index(deps, t) == 0) {
        if (deps == "") deps = t; else deps = deps " " t
      }
    }
  }
  print sid "|" deps
}' > "${deps_file}"

# Compute depths
awk -F'|' '{print $1 " 0"}' "${deps_file}" > "${depth_file}"
for pass in $(seq 1 30); do
  awk -F'|' -v df="${depth_file}" '
    BEGIN { while ((getline l < df) > 0) { split(l, a, " "); depth[a[1]] = a[2]+0 } }
    {
      sid=$1; deps=$2
      if (deps == "") { new_d = 1 } else {
        max_p = 0; np = split(deps, parr, " ")
        for (i=1; i<=np; i++) {
          p = parr[i]
          if (p in depth && depth[p] > max_p) max_p = depth[p]
        }
        new_d = max_p + 1
      }
      print sid " " new_d " " (new_d != depth[sid] ? "C" : "S")
    }
  ' "${deps_file}" > "${tmpd}/dcheck.txt"
  if ! grep -q " C$" "${tmpd}/dcheck.txt"; then break; fi
  awk '{print $1 " " $2}' "${tmpd}/dcheck.txt" > "${depth_file}"
done

# Print depths for S-21.xx, S-7.06-11, S-5.07, and some Partition B entries
echo "=== Depths for key stories ==="
grep -E "^(S-21\.|S-7\.0[6-9]|S-7\.1[0-1]|S-5\.07|S-4\.11|S-7\.04|S-7\.05|S-10\.01|S-14\.01|S-16\.01|S-15\.03|S-11\.) " "${depth_file}" | sort

